"""Independent per-pixel oracle for indexed-v1. All inputs are generated by this lab."""
import argparse
import hashlib
import json
import math
from pathlib import Path
import struct
import zlib

SIDE = 256
DEPTH_TOLERANCE = 1e-6
PALETTE = ((15, 27, 37), (248, 181, 91), (60, 182, 171), (84, 113, 185))


def front_contains(x, y):
    # Pixel centres in screen space. Positive area is clockwise in y-down coordinates.
    points = ((56, 88), (216, 56), (144, 216))
    for a, b in zip(points, points[1:] + points[:1]):
        dx, dy = b[0] - a[0], b[1] - a[1]
        side = dx * (y - a[1]) - dy * (x - a[0])
        inclusive = dy < 0 or (dy == 0 and dx > 0)
        if side < 0 or (side == 0 and not inclusive):
            return False
    return True


def expected(x, y):
    # Resolve the final visible surface analytically, independently of the GPU index stream.
    if front_contains(x, y):
        return 1, .125 + y / 2048
    if 32 <= x < 224 and 32 <= y < 224:
        return (2 if y <= x else 3), .5 + x / 1024
    return 0, 1.


def png(path, rgb):
    def chunk(tag, payload):
        return (struct.pack(">I", len(payload)) + tag + payload
                + struct.pack(">I", zlib.crc32(tag + payload)))
    rows = b"".join(b"\0" + rgb[y * SIDE * 3:(y + 1) * SIDE * 3] for y in range(SIDE))
    path.write_bytes(b"\x89PNG\r\n\x1a\n"
                     + chunk(b"IHDR", struct.pack(">IIBBBBB", SIDE, SIDE, 8, 2, 0, 0, 0))
                     + chunk(b"IDAT", zlib.compress(rows, 9)) + chunk(b"IEND", b""))


def compare(folder, images=None):
    ids = (folder / "ids.u8").read_bytes()
    depths = (folder / "depth.f32le").read_bytes()
    if len(ids) != SIDE**2 or len(depths) != SIDE**2 * 4:
        raise ValueError("Invalid attachment dimensions")
    bad_coverage = bad_ids = bad_depth = covered = 0
    max_error = 0.
    cpu, gpu = bytearray(), bytearray()
    for i, (depth,) in enumerate(struct.iter_unpack("<f", depths)):
        label, ref_depth = expected(i % SIDE + .5, i // SIDE + .5)
        ident = ids[i]
        covered += ident != 0
        bad_coverage += bool(label) != bool(ident)
        bad_ids += ident != label
        if not math.isfinite(depth):
            raise ValueError("Nonfinite depth readback")
        error = abs(depth - ref_depth)
        bad_depth += error > DEPTH_TOLERANCE
        max_error = max(max_error, error)
        if images:
            cpu.extend(PALETTE[label])
            gpu.extend(PALETTE[ident] if ident < len(PALETTE) else (255, 0, 255))
    if images:
        images.mkdir(parents=True, exist_ok=True)
        png(images / "reference.png", cpu)
        png(images / "rx570.png", gpu)
    return {"pixels": len(ids), "covered": covered, "coverage_mismatches": bad_coverage,
            "primitive_id_mismatches": bad_ids, "depth_mismatches": bad_depth,
            "max_abs_depth_error": max_error, "depth_tolerance": DEPTH_TOLERANCE,
            "id_sha256": hashlib.sha256(ids).hexdigest(),
            "depth_sha256": hashlib.sha256(depths).hexdigest()}


if __name__ == "__main__":
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("folder", type=Path)
    parser.add_argument("--images", type=Path, help="write palette previews for the RX 570 report")
    args = parser.parse_args()
    result = compare(args.folder, args.images)
    print(json.dumps(result))
    raise SystemExit(int(any(result[key] for key in
                             ("coverage_mismatches", "primitive_id_mismatches", "depth_mismatches"))))
